/** Convert a 1-2 letter column (uppercase) into its 1-based number, A=1..Z=26,AA=27..ZZ=702. */
export function colToNum(col) {
  let n = 0
  for (const ch of col) n = n * 26 + (ch.charCodeAt(0) - 64)
  return n
}

/** Convert a column number back into its 1-2 letter form. */
export function numToCol(n) {
  if (n <= 26) return String.fromCharCode(64 + n)
  const rest = n - 26
  const first = String.fromCharCode(64 + Math.floor((rest - 1) / 26) + 1)
  const second = String.fromCharCode(64 + ((rest - 1) % 26) + 1)
  return first + second
}

/**
 * Parse a strict sheet-declaration address: 1-2 letters, 1-3 digits, row >= 1.
 * Returns { col, row } (col upper-cased) or null when the text does not match.
 */
export function parseAddressStrict(text) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(text)
  if (!m) return null
  const row = parseInt(m[2], 10)
  if (row < 1) return null
  return { col: m[1].toUpperCase(), row }
}

/**
 * Parse a formula word (already upper-cased letters+digits) as an address candidate.
 * Returns { valid: true, col, row } when it is inside the addressable range, or
 * { valid: false } when it is a word the grammar accepts but that names no
 * addressable cell (wrong letter/digit counts, or row 0).
 */
export function parseAddressWord(word) {
  const m = /^([A-Z]+)([0-9]*)$/.exec(word)
  if (!m) return { valid: false }
  const letters = m[1]
  const digits = m[2]
  if (digits === '') return { valid: false }
  if (letters.length > 2 || digits.length > 3) return { valid: false }
  const row = parseInt(digits, 10)
  if (row < 1) return { valid: false }
  return { valid: true, col: letters, row }
}

/** Canonical map key for a column/row pair. */
export function addressKey(col, row) {
  return col + String(row)
}

/**
 * Expand the range between two formula words into its addressable cell keys,
 * in ascending column then row order. Returns null when either corner names
 * no addressable cell.
 */
export function resolveRangeCells(fromWord, toWord) {
  const a = parseAddressWord(fromWord)
  const b = parseAddressWord(toWord)
  if (!a.valid || !b.valid) return null
  const c1 = colToNum(a.col)
  const c2 = colToNum(b.col)
  const colMin = Math.min(c1, c2)
  const colMax = Math.max(c1, c2)
  const rowMin = Math.min(a.row, b.row)
  const rowMax = Math.max(a.row, b.row)
  const cells = []
  for (let c = colMin; c <= colMax; c++) {
    const letters = numToCol(c)
    for (let r = rowMin; r <= rowMax; r++) cells.push(addressKey(letters, r))
  }
  return cells
}
"}

