{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T235858Z/cell-SMb0pu/src/sheet.js","content":"import { parseAddressStrict, addressKey } from './address.js'

/** Thrown for the two ways a sheet can fail to parse; carries the exact message text. */
export class SheetError extends Error {}

/**
 * Split raw stdin into the sheet's declarations. Each entry is
 * { key, content, line }; duplicate or malformed addresses throw SheetError
 * with the exact wording the CLI must print.
 */
export function parseSheet(input) {
  let text = input
  if (text.endsWith('\n')) text = text.slice(0, -1)
  const lines = text === '' ? [] : text.split('\n')
  const cells = new Map()
  const order = []
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const stripped = raw.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped.startsWith('#')) continue
    const m = /^([^ \t]+)(?:[ \t]+(.*))?$/.exec(stripped)
    const addressText = m[1]
    const content = m[2] === undefined ? '' : m[2]
    const parsed = parseAddressStrict(addressText)
    if (!parsed) throw new SheetError(`error: line ${lineNo}: invalid cell address ${addressText}`)
    const key = addressKey(parsed.col, parsed.row)
    if (cells.has(key)) throw new SheetError(`error: line ${lineNo}: cell ${key} is declared twice`)
    cells.set(key, content)
    order.push(key)
  }
  return { cells, order }
}
"}

