export class LexError extends Error {}

const PUNCT = ['<=', '>=', '<>', '^', '*', '/', '+', '-', '=', '<', '>', '(', ')', ',', ':']

/** Tokenize a formula body (the text after the leading `=`). */
export function tokenize(body) {
  const tokens = []
  let i = 0
  while (i < body.length) {
    const ch = body[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (/[0-9]/.test(ch)) {
      let j = i + 1
      while (j < body.length && /[0-9]/.test(body[j])) j++
      if (body[j] === '.' && /[0-9]/.test(body[j + 1] || '')) {
        j++
        while (j < body.length && /[0-9]/.test(body[j])) j++
      }
      tokens.push({ type: 'NUMBER', text: body.slice(i, j) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      let j = i + 1
      while (j < body.length && /[A-Za-z]/.test(body[j])) j++
      while (j < body.length && /[0-9]/.test(body[j])) j++
      tokens.push({ type: 'WORD', text: body.slice(i, j) })
      i = j
      continue
    }
    const two = body.slice(i, i + 2)
    if (PUNCT.includes(two)) {
      tokens.push({ type: two, text: two })
      i += 2
      continue
    }
    const one = body.slice(i, i + 1)
    if (PUNCT.includes(one)) {
      tokens.push({ type: one, text: one })
      i += 1
      continue
    }
    throw new LexError(`unexpected character ${ch}`)
  }
  return tokens
}
"}

