  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }
  peek() {
    return this.tokens[this.pos]
  }
  next() {
    return this.tokens[this.pos++]
  }
  expect(type) {
    const t = this.next()
    if (!t || t.type !== type) throw new ParseError(`expected ${type}`)
    return t
  }
}

function parseComparison(cur) {
  let left = parseAdditive(cur)
  while (cur.peek() && COMPARISON_OPS.has(cur.peek().type)) {
    const op = cur.next().type
    const right = parseAdditive(cur)
    left = { type: 'Binary', op, left, right }
  }
  return left
}

function parseAdditive(cur) {
  let left = parseMultiplicative(cur)
  while (cur.peek() && ADDITIVE_OPS.has(cur.peek().type)) {
    const op = cur.next().type
    const right = parseMultiplicative(cur)
    left = { type: 'Binary', op, left, right }
  }
  return left
}

