  let left = parsePower(cur)
  while (cur.peek() && MULTIPLICATIVE_OPS.has(cur.peek().type)) {
    const op = cur.next().type
    const right = parsePower(cur)
    left = { type: 'Binary', op, left, right }
  }
  return left
}

