  const left = parseUnary(cur)
  if (cur.peek() && cur.peek().type === '^') {
    cur.next()
    const right = parsePower(cur)
    return { type: 'Binary', op: '^', left, right }
  }
  return left
}

function parseUnary(cur) {
  const t = cur.peek()
  if (t && (t.type === '+' || t.type === '-')) {
    cur.next()
    const operand = parseUnary(cur)
    return { type: 'Unary', op: t.type, operand }
  }
  return parsePrimary(cur)
}

function parsePrimary(cur) {
  const t = cur.next()
  if (!t) throw new ParseError('unexpected end of formula')
  if (t.type === 'NUMBER') return { type: 'Number', value: parseFloat(t.text) }
  if (t.type === '(') {
    const expr = parseComparison(cur)
    cur.expect(')')
    return { type: 'Paren', expr }
  }
  if (t.type === 'WORD') {
    const next = cur.peek()
    if (next && next.type === '(') {
      cur.next()
      const args = []
      if (cur.peek() && cur.peek().type !== ')') {
        args.push(parseComparison(cur))
        while (cur.peek() && cur.peek().type === ',') {
          cur.next()
          args.push(parseComparison(cur))
        }
      }
      cur.expect(')')
      return { type: 'Call', name: t.text.toUpperCase(), args }
    }
    if (next && next.type === ':') {
      cur.next()
      const w2 = cur.expect('WORD')
      return { type: 'Range', from: t.text.toUpperCase(), to: w2.text.toUpperCase() }
    }
    const upper = t.text.toUpperCase()
    if (upper === 'TRUE') return { type: 'Bool', value: true }
    if (upper === 'FALSE') return { type: 'Bool', value: false }
    return { type: 'Address', word: upper }
  }
  throw new ParseError(`unexpected token ${t.text}`)
