export function parseFormula(body) {
  const tokens = tokenize(body)
  const cur = new Cursor(tokens)
  const ast = parseComparison(cur)
  if (cur.peek() !== undefined) throw new ParseError('trailing tokens')
  return ast
}

export { LexError }
