export const NUM = (v) => ({ t: 'num', v })
export const TEXT = (v) => ({ t: 'text', v })
export const BOOL = (v) => ({ t: 'bool', v })
export const ERR = (v) => ({ t: 'err', v })

const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

const NUMBER_LITERAL = /^-?[0-9]+(\.[0-9]+)?$/

/** Parse a literal (non-formula) cell content into a Value. */
export function parseLiteral(content) {
  if (content === '') return NUM(0)
  if (ERROR_TOKENS.has(content)) return ERR(content)
  if (NUMBER_LITERAL.test(content)) return NUM(parseFloat(content))
  return TEXT(content)
}

/** Convert a non-error value to a number for arithmetic, or #VALUE! for text. */
export function toNumberOrErr(v) {
  if (v.t === 'num') return v
  if (v.t === 'bool') return NUM(v.v ? 1 : 0)
  if (v.t === 'err') return v
  return ERR('#VALUE!')
}
"}

