import { readFileSync } from 'node:fs'
import { colToNum, parseAddressWord } from './address.js'
import { parseSheet, SheetError } from './sheet.js'
import { Evaluator } from './evaluator.js'
import { collectDeps } from './deps.js'
import { formatNumber } from './format.js'

function fail(message) {
  process.stderr.write(message + '\n')
  process.exit(2)
}

function sortKeys(keys) {
  return [...keys].sort((a, b) => {
    const pa = parseAddressWord(a)
    const pb = parseAddressWord(b)
    const ca = colToNum(pa.col)
    const cb = colToNum(pb.col)
    if (ca !== cb) return ca - cb
    return pa.row - pb.row
  })
}

function formatValue(v) {
  if (v.t === 'num') return formatNumber(v.v)
  if (v.t === 'err') return v.v
  if (v.t === 'bool') return v.v ? 'TRUE' : 'FALSE'
  return v.v
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
    fail('error: usage: cli.js values|deps')
  }

  const input = readFileSync(0, 'utf8')
  let sheet
  try {
    sheet = parseSheet(input)
  } catch (e) {
    if (e instanceof SheetError) fail(e.message)
    throw e
  }

  const keys = sortKeys(sheet.cells.keys())

  if (mode === 'values') {
    const evaluator = new Evaluator(sheet.cells)
    const lines = keys.map((key) => `${key}=${formatValue(evaluator.getCellValue(key))}`)
    process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
    return
  }

  const evaluator = new Evaluator(sheet.cells)
  const lines = keys.map((key) => {
    const content = sheet.cells.get(key)
    const out = new Set()
    if (content.startsWith('=')) {
      const ast = evaluator.getAst(content)
      if (ast !== 'invalid') collectDeps(ast, out)
    }
    const deps = sortKeys(out)
    return deps.length ? `${key}: ${deps.join(' ')}` : `${key}:`
  })
  process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
}

main()
